import { test } from "node:test";
import assert from "node:assert/strict";
import { HookBus } from "../src/bus.ts";
import { registerAuditPlugin, type ToolResult } from "../src/plugin.ts";

test("handlers run sequentially in subscription order and emit waits for all", async () => {
  const bus = new HookBus();
  const log: string[] = [];
  bus.on("e", async () => {
    log.push("a:start");
    await new Promise((r) => setTimeout(r, 10));
    log.push("a:end");
  });
  bus.on("e", () => {
    log.push("b");
  });
  await bus.emit("e", null);
  assert.deepEqual(log, ["a:start", "a:end", "b"]);
});

test("a throwing handler rejects emit and stops later handlers", async () => {
  const bus = new HookBus();
  let ran = false;
  bus.on("e", () => {
    throw new Error("boom");
  });
  bus.on("e", () => {
    ran = true;
  });
  await assert.rejects(bus.emit("e", null), /boom/);
  assert.equal(ran, false);
});

test("self-unsubscribe during emit does not skip the next handler", async () => {
  const bus = new HookBus();
  const log: string[] = [];
  const off = bus.on("e", () => {
    off();
    log.push("once");
  });
  bus.on("e", () => log.push("second"));
  await bus.emit("e", null);
  await bus.emit("e", null);
  assert.deepEqual(log, ["once", "second", "second"]);
});

test("audit plugin: notice, redaction, then audit log", async () => {
  const bus = new HookBus();
  const audit: string[] = [];
  registerAuditPlugin(bus, audit);
  const result: ToolResult = { tool: "bash", output: "password=hunter2 ok" };
  await bus.emit("tool.after", result);
  assert.deepEqual(audit, ["notice: tool output is audited", "bash: password=[redacted] ok"]);
});
